select case when year(c.signup_date) < 2024 then 'before_2024' when year(c.signup_date) = 2024 then '2024' else 'after_2024' end as signup_cohort, sum(case when o.channel = 'store' then 1 else 0 end) as store_count from orders o join customers c on o.customer_id = c.id where c.age between 43 and 52 group by case when year(c.signup_date) < 2024 then 'before_2024' when year(c.signup_date) = 2024 then '2024' else 'after_2024' end
